// Latency comparison (starter)
// kernel bypass filter generated by KBF Studio (c++ mode)
// generated 2026-09-29 16:40
// tiles: 9   wires: 9
// 
//   Axon feed                data_stream    id stream
//   Network Card             nic            id nic
//   Kernel / CPU Path        kernel_path    id kernel
//   Kernel Bypass            kernel_bypass  id bypass
//   Memory Store             memory         id memory
//   Snippet Definer          snippet        id snippet
//   Timestamp                timestamp      id stamp
//   Processor                processor      id proc
//   Latency Meter            latency_meter  id meter
// 
//   Axon feed  -->  Network Card
//   Network Card  -->  Kernel / CPU Path
//   Network Card  -->  Kernel Bypass
//   Kernel / CPU Path  -->  Memory Store
//   Kernel Bypass  -->  Snippet Definer
//   Snippet Definer  -->  Timestamp
//   Timestamp  -->  Processor
//   Processor  -->  Latency Meter
//   Latency Meter  -->  Memory Store
//
// Build:  c++ -O2 -std=c++17 -o kbf_filter kbf_filter.cpp
// Run:    ./kbf_filter                     simulate with a virtual clock
//         sudo ./kbf_filter --live eth0    read real frames from a NIC (Linux)
//         ./kbf_filter --udp 5555          listen on a UDP port
//         ./kbf_filter --max-packets N --seconds S --json --out DIR
//
// Tile API (each tile lives in its own namespace; P is its settings):
//   int  process(Packet& pkt, Ctx& ctx)     return 1 = pass, 0 = drop
//   bool generate(Ctx& ctx, Packet& pkt)    simulation source: fill pkt, return true; false = finished
//   void setup(Ctx&) / finish(Ctx&)         optional, run once
//   ctx.now(pkt) ctx.delay(pkt,ns) ctx.log(s) ctx.report(name,json) ctx.request_stop() ctx.gauss(sd)
//   kbf_parse(pkt) kbf_pct(v,q) kbf_mean(v) kbf_put16/32/64 kbf_get16/32/64 kbf_path_name(p)
//
// True kernel bypass: replace kbf_live_open()/kbf_live_read() with your DPDK / AF_XDP / ef_vi receive loop.
